#[test]
fn power_shows_at_45_kmh() {
    use shell_simulator::ant::device_type;
    use shell_simulator::route::Point;
    use shell_simulator::route::Route;
    let mut sim = shell_simulator::sim::Sim::new();
    sim.ant_sensor(device_type::HEART_RATE, 4242);
    sim.ant_sensor(device_type::POWER, 1234);
    sim.ride_route(Route::profile(
        Point::new(-33.45, -70.66),
        &[(0.0, 0.0), (633.0, 0.0)],
    ));
    sim.ride_at(0.0, 0.0, 72.0, 0.0);
    sim.advance(10);
    sim.ride_at(0.0, 0.0, 0.0, 0.0);
    sim.advance(3700);
    sim.pair(&["HEART RATE", "POWER METER"]);
    sim.set_gps_fix(true);
    sim.advance(50);
    sim.ride_at(25.0, 180.0, 130.0, 85.0);
    sim.start_ride();
    sim.advance(6910);
    sim.set_present(device_type::POWER, 1234, false);
    sim.set_present(device_type::HEART_RATE, 4242, false);
    sim.advance(4240);
    sim.set_present(device_type::HEART_RATE, 4242, true);
    sim.set_present(device_type::POWER, 1234, true);
    sim.advance(8500);
    sim.set_present(device_type::POWER, 1234, false);
    sim.set_present(device_type::HEART_RATE, 4242, false);
    sim.advance(1100);
    sim.set_present(device_type::HEART_RATE, 4242, true);
    sim.set_present(device_type::POWER, 1234, true);
    sim.advance(6450);
    sim.set_present(device_type::POWER, 1234, false);
    sim.set_present(device_type::HEART_RATE, 4242, false);
    sim.advance(3950);
    sim.set_present(device_type::HEART_RATE, 4242, true);
    sim.set_present(device_type::POWER, 1234, true);
    sim.advance(8800);
    sim.set_present(device_type::POWER, 1234, false);
    sim.set_present(device_type::HEART_RATE, 4242, false);
    sim.advance(800);
    sim.set_present(device_type::HEART_RATE, 4242, true);
    sim.set_present(device_type::POWER, 1234, true);
    sim.advance(9350);
    sim.set_present(device_type::POWER, 1234, false);
    sim.set_present(device_type::HEART_RATE, 4242, false);
    sim.advance(1050);
    sim.set_present(device_type::POWER, 1234, true);
    sim.advance(250);
    sim.set_present(device_type::HEART_RATE, 4242, true);
    sim.advance(8800);
    sim.set_present(device_type::POWER, 1234, false);
    sim.set_present(device_type::HEART_RATE, 4242, false);
    sim.advance(550);
    sim.set_present(device_type::POWER, 1234, true);
    sim.advance(50);
    sim.ride_at(25.0, 320.0, 130.0, 95.0);
    sim.advance(220);
    sim.set_present(device_type::HEART_RATE, 4242, true);
    sim.advance(780);
    sim.ride_at(45.0, 320.0, 160.0, 95.0);
    sim.advance(8400);
    sim.set_present(device_type::POWER, 1234, false);
    sim.set_present(device_type::HEART_RATE, 4242, false);
    sim.advance(250);
    sim.set_present(device_type::HEART_RATE, 4242, true);
    sim.set_present(device_type::POWER, 1234, true);
    sim.advance(4800);
    sim.set_present(device_type::POWER, 1234, false);
    sim.set_present(device_type::HEART_RATE, 4242, false);
    sim.advance(800);
    sim.set_present(device_type::HEART_RATE, 4242, true);
    sim.set_present(device_type::POWER, 1234, true);
    sim.advance(1800);
    shell_simulator::trace::fixture::expect(
        &mut sim,
        &["power!=--"],
        None,
        &["speed=45.0", "cad=95", "hr=160"],
    );
}

#[cfg(feature = "planted-reading-bug")]
#[test]
#[should_panic(expected = "power!=-- fails: got --")]
fn the_planted_reading_bug_makes_power_shows_at_45_kmh_fail() {
    power_shows_at_45_kmh();
}

